/**
 * @summary List downloaded media
 */
export const getListMediaUrl = (params?: ListMediaParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/media?${stringifiedParams}` : `/api/media`
}

export const listMedia = async (params?: ListMediaParams, options?: RequestInit): Promise<MediaItem[]> => {

  return customFetch<MediaItem[]>(getListMediaUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListMediaQueryKey = (params?: ListMediaParams,) => {
    return [
    `/api/media`, ...(params ? [params] : [])
    ] as const;
    }


export const getListMediaQueryOptions = <TData = Awaited<ReturnType<typeof listMedia>>, TError = ErrorType<unknown>>(params?: ListMediaParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listMedia>>, TError, TData>, }
) => {

const {query: queryOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListMediaQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listMedia>>> = ({ signal }) => listMedia(params, { signal });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listMedia>>, TError, TData> & { queryKey: QueryKey }
}

export type ListMediaQueryResult = NonNullable<Awaited<ReturnType<typeof listMedia>>>
export type ListMediaQueryError = ErrorType<unknown>


